17	package org.springframework.boot.system;
18	
19	import java.io.File;
20	import java.io.IOException;
21	import java.io.UncheckedIOException;
22	import java.nio.file.FileSystem;
23	import java.nio.file.Files;
24	import java.nio.file.LinkOption;
25	import java.nio.file.Path;
26	import java.nio.file.Paths;
27	import java.nio.file.attribute.FileAttribute;
28	import java.nio.file.attribute.PosixFileAttributes;
29	import java.nio.file.attribute.PosixFilePermission;
30	import java.nio.file.attribute.PosixFilePermissions;
31	import java.nio.file.attribute.UserPrincipal;
32	import java.security.MessageDigest;
33	import java.util.EnumSet;
34	import java.util.HexFormat;
35	import java.util.concurrent.locks.Lock;
36	import java.util.concurrent.locks.ReentrantLock;
37	
38	import org.jspecify.annotations.Nullable;
39	
40	import org.springframework.core.NativeDetector;
41	import org.springframework.util.Assert;
42	import org.springframework.util.StringUtils;
43	
44	/**
45	 * Provides access to an application specific temporary directory. Generally speaking
46	 * different Spring Boot applications will get different locations, however, simply
47	 * restarting an application will give the same location.
48	 *
49	 * @author Phillip Webb
50	 * @since 2.0.0
51	 */
52	public class ApplicationTemp {
53	
54		private static final FileAttribute<?>[] NO_FILE_ATTRIBUTES = {};
55	
56		private static final EnumSet<PosixFilePermission> DIRECTORY_PERMISSIONS = EnumSet.of(PosixFilePermission.OWNER_READ,
57				PosixFilePermission.OWNER_WRITE, PosixFilePermission.OWNER_EXECUTE);
58	
59		private final @Nullable Class<?> sourceClass;
60	
61		private final Lock pathLock = new ReentrantLock();
62	
63		private final @Nullable UserPrincipal directoryOwner;
64	
65		private volatile @Nullable Path path;
66	
67		/**
68		 * Create a new {@link ApplicationTemp} instance.
69		 */
70		public ApplicationTemp() {
71			this(null);
72		}
73	
74		/**
75		 * Create a new {@link ApplicationTemp} instance for the specified source class.
76		 * @param sourceClass the source class or {@code null}
77		 */
78		public ApplicationTemp(@Nullable Class<?> sourceClass) {
79			this.sourceClass = sourceClass;
80			this.directoryOwner = directoryOwner();
81		}
82	
83		private static @Nullable UserPrincipal directoryOwner() {
84			try {
85				Path tempFile = Files.createTempFile("application-temp", "-owner");
86				UserPrincipal owner = Files.getOwner(tempFile);
87				Files.delete(tempFile);
88				return owner;
89			}
90			catch (UnsupportedOperationException ex) {
91				return null;
92			}
93			catch (IOException ex) {
94				throw new UncheckedIOException(ex);
95			}
96		}
97	
98		@Override
99		public String toString() {
100			return getDir().getAbsolutePath();
101		}
102	
103		/**
104		 * Return the directory to be used for application specific temp files.
105		 * @return the application temp directory
106		 */
107		public File getDir() {
108			return getPath().toFile();
109		}
110	
111		/**
112		 * Return a subdirectory of the application temp.
113		 * @param subDir the subdirectory name
114		 * @return a subdirectory
115		 */
116		public File getDir(String subDir) {
117			return createDirectory(getPath().resolve(subDir)).toFile();
118		}
119	
120		private Path getPath() {
121			if (this.path == null) {
122				this.pathLock.lock();
123				try {
124					if (this.path == null) {
125						String hash = HexFormat.of().withUpperCase().formatHex(generateHash(this.sourceClass));
126						this.path = createDirectory(getTempDirectory().resolve(hash));
127					}
128				}
129				finally {
130					this.pathLock.unlock();
131				}
132			}
133			Path path = this.path;
134			Assert.state(path != null, "'path' must not be null");
135			return path;
136		}
137	
138		private Path createDirectory(Path path) {
139			try {
140				FileSystem fileSystem = path.getFileSystem();
141				if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
142					Files.createDirectory(path, asFileAttributes(fileSystem, DIRECTORY_PERMISSIONS));
143				}
144				else {
145					if (supportsPosixView(fileSystem)) {
146						PosixFileAttributes attributes = Files.readAttributes(path, PosixFileAttributes.class,
147								LinkOption.NOFOLLOW_LINKS);
148						Assert.state(attributes.isDirectory(),
149								() -> "'" + path + "' already exists but it is not a directory");
150						Assert.state(DIRECTORY_PERMISSIONS.equals(attributes.permissions()), () -> "Existing directory '"
151								+ path + "' does not have the permissions " + DIRECTORY_PERMISSIONS);
152						assertDirectoryOwnership(attributes.owner(), path);
153					}
154					else {
155						Assert.state(Files.isDirectory(path, LinkOption.NOFOLLOW_LINKS),
156								() -> "'" + path + "' already exists but it is not a directory");
157						try {
158							assertDirectoryOwnership(Files.getOwner(path, LinkOption.NOFOLLOW_LINKS), path);
159						}
160						catch (UnsupportedOperationException ex) {
161							// Ownership check not supported. Continue.
162						}
163					}
164				}
165				return path;
166			}
167			catch (IOException ex) {
168				throw new IllegalStateException("Unable to create application temp directory " + path, ex);
169			}
170		}
171	
172		private void assertDirectoryOwnership(UserPrincipal owner, Path path) {
173			if (this.directoryOwner != null) {
174				Assert.state(this.directoryOwner.equals(owner),
175						() -> "Existing directory '" + path + "' is not owned by " + this.directoryOwner.getName());
176			}
177		}
178	
179		private FileAttribute<?>[] asFileAttributes(FileSystem fileSystem, EnumSet<PosixFilePermission> ownerReadWrite) {
180			if (!supportsPosixView(fileSystem)) {
181				return NO_FILE_ATTRIBUTES;
182			}
183			return new FileAttribute<?>[] { PosixFilePermissions.asFileAttribute(ownerReadWrite) };
184		}
185	
186		private boolean supportsPosixView(FileSystem fileSystem) {
187			return fileSystem.supportedFileAttributeViews().contains("posix");
188		}
189	
190		private Path getTempDirectory() {
191			String property = System.getProperty("java.io.tmpdir");
192			Assert.state(StringUtils.hasLength(property), "No 'java.io.tmpdir' property set");
193			Path tempDirectory = Paths.get(property);
194			Assert.state(Files.exists(tempDirectory), () -> "Temp directory '" + tempDirectory + "' does not exist");
195			Assert.state(Files.isDirectory(tempDirectory),
196					() -> "Temp location '" + tempDirectory + "' is not a directory");
197			return tempDirectory;
198		}
199	
200		private byte[] generateHash(@Nullable Class<?> sourceClass) {
201			ApplicationHome home = new ApplicationHome(sourceClass);
202			MessageDigest digest;
203			try {
204				digest = MessageDigest.getInstance("SHA-1");
205				update(digest, home.getSource());
206				update(digest, home.getDir());
207				update(digest, System.getProperty("user.dir"));
208				if (!NativeDetector.inNativeImage()) {
209					update(digest, System.getProperty("java.home"));
210				}
211				update(digest, System.getProperty("java.class.path"));
212				update(digest, System.getProperty("sun.java.command"));
213				update(digest, System.getProperty("sun.boot.class.path"));
214				return digest.digest();
215			}
216			catch (Exception ex) {
217				throw new IllegalStateException(ex);
218			}
219		}
220	
221		private void update(MessageDigest digest, @Nullable Object source) {
222			if (source != null) {
223				digest.update(getUpdateSourceBytes(source));
224			}
225		}
226	
227		private byte[] getUpdateSourceBytes(Object source) {
228			if (source instanceof File file) {
229				return getUpdateSourceBytes(file.getAbsolutePath());
230			}
231			return source.toString().getBytes();
232		}
233	
234	}
