17	package org.springframework.boot.util;
18	
19	import java.lang.reflect.Constructor;
20	import java.util.Arrays;
21	import java.util.Collection;
22	import java.util.Collections;
23	import java.util.Comparator;
24	import java.util.LinkedHashMap;
25	import java.util.List;
26	import java.util.Map;
27	import java.util.function.Consumer;
28	import java.util.function.Function;
29	import java.util.function.Supplier;
30	import java.util.stream.Stream;
31	
32	import org.jspecify.annotations.Nullable;
33	
34	import org.springframework.core.annotation.AnnotationAwareOrderComparator;
35	import org.springframework.util.Assert;
36	import org.springframework.util.ClassUtils;
37	import org.springframework.util.ReflectionUtils;
38	
39	/**
40	 * Simple factory used to instantiate objects by injecting available parameters.
41	 *
42	 * @param <T> the type to instantiate
43	 * @author Phillip Webb
44	 * @author Scott Frederick
45	 * @since 2.4.0
46	 */
47	public class Instantiator<T> {
48	
49		private static final Comparator<Constructor<?>> CONSTRUCTOR_COMPARATOR = Comparator
50			.<Constructor<?>>comparingInt(Constructor::getParameterCount)
51			.reversed();
52	
53		private static final FailureHandler throwingFailureHandler = (type, implementationName, failure) -> {
54			throw new IllegalArgumentException("Unable to instantiate " + implementationName + " [" + type.getName() + "]",
55					failure);
56		};
57	
58		private final Class<?> type;
59	
60		private final Map<Class<?>, Function<Class<?>, @Nullable Object>> availableParameters;
61	
62		private final FailureHandler failureHandler;
63	
64		/**
65		 * Create a new {@link Instantiator} instance for the given type.
66		 * @param type the type to instantiate
67		 * @param availableParameters consumer used to register available parameters
68		 */
69		public Instantiator(Class<?> type, Consumer<AvailableParameters> availableParameters) {
70			this(type, availableParameters, throwingFailureHandler);
71		}
72	
73		/**
74		 * Create a new {@link Instantiator} instance for the given type.
75		 * @param type the type to instantiate
76		 * @param availableParameters consumer used to register available parameters
77		 * @param failureHandler a {@link FailureHandler} that will be called in case of
78		 * failure when instantiating objects
79		 * @since 2.7.0
80		 */
81		public Instantiator(Class<?> type, Consumer<AvailableParameters> availableParameters,
82				FailureHandler failureHandler) {
83			this.type = type;
84			this.availableParameters = getAvailableParameters(availableParameters);
85			this.failureHandler = failureHandler;
86		}
87	
88		private Map<Class<?>, Function<Class<?>, @Nullable Object>> getAvailableParameters(
89				Consumer<AvailableParameters> availableParameters) {
90			Map<Class<?>, Function<Class<?>, @Nullable Object>> result = new LinkedHashMap<>();
91			availableParameters.accept(new AvailableParameters() {
92	
93				@Override
94				public void add(Class<?> type, @Nullable Object instance) {
95					result.put(type, (factoryType) -> instance);
96				}
97	
98				@Override
99				public void add(Class<?> type, Function<Class<?>, @Nullable Object> factory) {
100					result.put(type, factory);
101				}
102	
103			});
104			return Collections.unmodifiableMap(result);
105		}
106	
107		/**
108		 * Instantiate the given set of class name, injecting constructor arguments as
109		 * necessary.
110		 * @param names the class names to instantiate
111		 * @return a list of instantiated instances
112		 */
113		public List<T> instantiate(Collection<String> names) {
114			return instantiate(null, names);
115		}
116	
117		/**
118		 * Instantiate the given set of class name, injecting constructor arguments as
119		 * necessary.
120		 * @param classLoader the source classloader
121		 * @param names the class names to instantiate
122		 * @return a list of instantiated instances
123		 * @since 2.4.8
124		 */
125		public List<T> instantiate(@Nullable ClassLoader classLoader, Collection<String> names) {
126			Assert.notNull(names, "'names' must not be null");
127			return instantiate(names.stream().map((name) -> TypeSupplier.forName(classLoader, name)));
128		}
129	
130		/**
131		 * Instantiate the given set of class name, injecting constructor arguments as
132		 * necessary.
133		 * @param name the class name to instantiate
134		 * @return an instantiated instance
135		 * @since 3.4.0
136		 */
137		public @Nullable T instantiate(String name) {
138			return instantiate(null, name);
139		}
140	
141		/**
142		 * Instantiate the given set of class name, injecting constructor arguments as
143		 * necessary.
144		 * @param classLoader the source classloader
145		 * @param name the class name to instantiate
146		 * @return an instantiated instance
147		 * @since 3.4.0
148		 */
149		public @Nullable T instantiate(@Nullable ClassLoader classLoader, String name) {
150			return instantiate(TypeSupplier.forName(classLoader, name));
151		}
152	
153		/**
154		 * Instantiate the given class, injecting constructor arguments as necessary.
155		 * @param type the type to instantiate
156		 * @return an instantiated instance
157		 * @since 3.4.0
158		 */
159		public @Nullable T instantiateType(Class<?> type) {
160			Assert.notNull(type, "'type' must not be null");
161			return instantiate(TypeSupplier.forType(type));
162		}
163	
164		/**
165		 * Instantiate the given set of classes, injecting constructor arguments as necessary.
166		 * @param types the types to instantiate
167		 * @return a list of instantiated instances
168		 * @since 2.4.8
169		 */
170		public List<T> instantiateTypes(Collection<Class<?>> types) {
171			Assert.notNull(types, "'types' must not be null");
172			return instantiate(types.stream().map(TypeSupplier::forType));
173		}
174	
175		/**
176		 * Get an injectable argument instance for the given type. This method can be used
177		 * when manually instantiating an object without reflection.
178		 * @param <A> the argument type
179		 * @param type the argument type
180		 * @return the argument to inject or {@code null}
181		 * @since 3.4.0
182		 */
183		@SuppressWarnings("unchecked")
184		public <A> @Nullable A getArg(Class<A> type) {
185			Assert.notNull(type, "'type' must not be null");
186			Function<Class<?>, Object> parameter = getAvailableParameter(type);
187			Assert.state(parameter != null, "Unknown argument type " + type.getName());
188			return (A) parameter.apply(this.type);
189		}
190	
191		private List<T> instantiate(Stream<TypeSupplier> typeSuppliers) {
192			return typeSuppliers.map(this::instantiate).sorted(AnnotationAwareOrderComparator.INSTANCE).toList();
193		}
194	
195		private @Nullable T instantiate(TypeSupplier typeSupplier) {
196			try {
197				Class<?> type = typeSupplier.get();
198				Assert.state(this.type.isAssignableFrom(type), () -> type + " is not assignable to " + this.type);
199				return instantiate(type);
200			}
201			catch (Throwable ex) {
202				this.failureHandler.handleFailure(this.type, typeSupplier.getName(), ex);
203				return null;
204			}
205		}
206	
207		@SuppressWarnings("unchecked")
208		private T instantiate(Class<?> type) throws Exception {
209			Constructor<?>[] constructors = type.getDeclaredConstructors();
210			Arrays.sort(constructors, CONSTRUCTOR_COMPARATOR);
211			for (Constructor<?> constructor : constructors) {
212				Object[] args = getArgs(constructor.getParameterTypes());
213				if (args != null) {
214					ReflectionUtils.makeAccessible(constructor);
215					return (T) constructor.newInstance(args);
216				}
217			}
218			throw new IllegalAccessException("Class [" + type.getName() + "] has no suitable constructor");
219		}
220	
221		private Object @Nullable [] getArgs(Class<?>[] parameterTypes) {
222			Object[] args = new Object[parameterTypes.length];
223			for (int i = 0; i < parameterTypes.length; i++) {
224				Function<Class<?>, Object> parameter = getAvailableParameter(parameterTypes[i]);
225				if (parameter == null) {
226					return null;
227				}
228				args[i] = parameter.apply(this.type);
229			}
230			return args;
231		}
232	
233		private @Nullable Function<Class<?>, Object> getAvailableParameter(Class<?> parameterType) {
