40	@SuppressWarnings("rawtypes")
41	abstract class LenientObjectToEnumConverterFactory<T> implements ConverterFactory<T, Enum<?>> {
42	
43		private static final Map<String, List<String>> ALIASES;
44	
45		static {
46			MultiValueMap<String, String> aliases = new LinkedMultiValueMap<>();
47			aliases.add("true", "on");
48			aliases.add("false", "off");
49			ALIASES = Collections.unmodifiableMap(aliases);
50		}
51	
52		@Override
53		@SuppressWarnings("unchecked")
54		public <E extends Enum<?>> Converter<T, E> getConverter(Class<E> targetType) {
55			Class<?> enumType = targetType;
56			while (enumType != null && !enumType.isEnum()) {
57				enumType = enumType.getSuperclass();
58			}
59			Assert.notNull(enumType, () -> "The target type " + targetType.getName() + " does not refer to an enum");
60			return new LenientToEnumConverter<>((Class<E>) enumType);
61		}
62	
63		@SuppressWarnings("unchecked")
64		private class LenientToEnumConverter<E extends Enum> implements Converter<T, @Nullable E> {
65	
66			private final Class<E> enumType;
67	
68			LenientToEnumConverter(Class<E> enumType) {
69				this.enumType = enumType;
70			}
71	
72			@Override
73			public @Nullable E convert(T source) {
74				String value = source.toString().trim();
75				if (value.isEmpty()) {
76					return null;
77				}
78				try {
79					return (E) Enum.valueOf(this.enumType, value);
80				}
81				catch (Exception ex) {
82					return findEnum(value);
83				}
84			}
85	
86			private E findEnum(String value) {
87				String name = getCanonicalName(value);
88				List<String> aliases = ALIASES.getOrDefault(name, Collections.emptyList());
89				for (E candidate : (Set<E>) EnumSet.allOf(this.enumType)) {
90					String candidateName = getCanonicalName(candidate.name());
91					if (name.equals(candidateName) || aliases.contains(candidateName)) {
92						return candidate;
93					}
94				}
95				throw new IllegalArgumentException("No enum constant " + this.enumType.getCanonicalName() + "." + value);
96			}
97	
98			private String getCanonicalName(String name) {
99				StringBuilder canonicalName = new StringBuilder(name.length());
100				name.chars()
101					.filter(Character::isLetterOrDigit)
102					.map(Character::toLowerCase)
103					.forEach((c) -> canonicalName.append((char) c));
104				return canonicalName.toString();
105			}
